// Reads the paper-trading simulation and alerts when a VERIFIED KuCoin -> MEXC LUNC gap was just seen.
// Alert only: this workflow places no orders and holds no exchange keys.
const d = $input.first().json;
const now = Date.now();
const MAX_AGE_MIN = 7;
const t = (d.trades || []).find(x => x.coin === 'LUNC' && x.buy === 'kucoin' && x.sell === 'mexc' && (now - x.t) < MAX_AGE_MIN * 60000);
const sd = $getWorkflowStaticData('global');
if (!t || sd.lastTradeT === t.t) return [{ json: { send: false } }];
sd.lastTradeT = t.t;
const live = (d.live || []).find(r => r.base === 'LUNC' && r.buy === 'kucoin' && r.sell === 'mexc');
const f = (x, n) => Number(x).toFixed(n);
let text = 'LUNC gap: buy KuCoin -> sell MEXC (verified by order book)\n' +
  'Net after fees: ' + f(t.net * 100, 2) + '%  |  est. profit on $' + t.size + ': $' + f(t.profit, 2) + '\n' +
  'KuCoin buy avg: ' + t.buyAvg + '  |  MEXC sell avg: ' + t.sellAvg + '\n';
if (live) text += 'Live now: net ' + f(live.net * 100, 2) + '%, top-of-book $' + (live.liq == null ? '?' : f(live.liq, 0)) + '\n';
text += 'Flat cost: ~$0.40 LUNC withdrawal fee (8000 LUNC) + ~$0 USDT back. Check live prices before acting. Start small.';
return [{ json: { send: true, text } }];
